import { readFileSync, writeFileSync } from 'fs';
const p = 'tools/pcb_templates/export.mjs';
let s = readFileSync(p, 'utf8');
const neu = readFileSync('tools/pcb_templates/_hand_analog_ic.mjs', 'utf8').trimEnd() + '\n\n';
const start = s.indexOf('function handLayoutLabAnalogIc(doc)');
const end = s.indexOf('function handLayoutLabDiscrete(doc)');
if (start < 0 || end < 0) {
  console.error('markers', start, end);
  process.exit(1);
}
// include leading comment block
let cStart = s.lastIndexOf('/**', start);
if (cStart < 0 || start - cStart > 200) cStart = start;
s = s.slice(0, cStart) + neu + s.slice(end);
s = s.replace(
  "id === 'lab_passive' || id === 'lab_discrete' || id === 'lab_analog_ic'",
  "id === 'lab_passive' || id === 'lab_discrete'"
);
if (!s.includes("id === 'lab_uart' || id === 'lab_analog_ic'")) {
  s = s.replace(
    "id === 'lab_51_led' || id === 'lab_uart'",
    "id === 'lab_51_led' || id === 'lab_uart' || id === 'lab_analog_ic'"
  );
}
writeFileSync(p, s);
console.log('ok', (s.match(/function handLayoutLabAnalogIc/g) || []).length);
console.log('hasDxA', s.includes('dxA = 40'));
console.log('cu4', s.includes("lab_uart' || id === 'lab_analog_ic'"));
